import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { createRequire } from 'node:module';
import path from 'node:path';

import { UNSUPPORTED_ON_WORKERS_NODES } from './unsupported-nodes.mjs';

const require = createRequire(import.meta.url);
const out = new URL('../src/generated/', import.meta.url).pathname;
mkdirSync(out, { recursive: true });

// `specifier` is how the generated file imports a source path. The langchain package has an
// `exports` map without its dist files, so its imports go through node_modules by path.
const PACKAGES = [
	{ name: 'n8n-nodes-base', specifier: (sourcePath) => `n8n-nodes-base/${sourcePath}` },
	{
		name: '@n8n/n8n-nodes-langchain',
		specifier: (sourcePath) => `../../node_modules/@n8n/n8n-nodes-langchain/${sourcePath}`,
	},
].map((pkg) => ({ ...pkg, dir: path.dirname(require.resolve(`${pkg.name}/package.json`)) }));

const HEADER = '// Generated by scripts/generate-registry.mjs. Do not edit.\n';
// Stock nodes that the worker replaces with its own class, by package and node name. Paths are relative to src/generated.
const NODE_OVERRIDES = {
	'n8n-nodes-base': { function: '../runtime/legacy-function', functionItem: '../runtime/legacy-function' },
};
const readKnown = (pkg, kind) => JSON.parse(readFileSync(path.join(pkg.dir, `dist/known/${kind}.json`), 'utf8'));

function loaderEntries(pkg, known, overrides = {}) {
	return Object.entries(known)
		.sort(([a], [b]) => a.localeCompare(b))
		.map(([name, { className, sourcePath }]) => {
			const spec = JSON.stringify(Object.hasOwn(overrides, name) ? overrides[name] : pkg.specifier(sourcePath));
			return `\t\t${JSON.stringify(name)}: async () => instantiate(await import(${spec}), ${JSON.stringify(className)}),`;
		});
}

const nodeBlocks = PACKAGES.map(
	(pkg) => `\t${JSON.stringify(pkg.name)}: {\n${loaderEntries(pkg, readKnown(pkg, 'nodes'), NODE_OVERRIDES[pkg.name]).join('\n')}\n\t},`,
);

writeFileSync(
	path.join(out, 'node-loaders.ts'),
	`${HEADER}import type { INodeType, IVersionedNodeType } from 'n8n-workflow';

import { instantiate } from '../runtime/instantiate';

/** Node loaders by package name, then by node name without the package prefix. */
export const nodeLoaders: Record<string, Record<string, () => Promise<INodeType | IVersionedNodeType>>> = {
${nodeBlocks.join('\n')}
};

/** Node types that cannot run on Workers, with the reason. From scripts/unsupported-nodes.mjs. */
export const unsupportedNodes: Record<string, string> = ${JSON.stringify(UNSUPPORTED_ON_WORKERS_NODES, null, '\t')};
`,
);

const credentialEntries = [];
const supportedNodes = {};
for (const pkg of PACKAGES) {
	const known = readKnown(pkg, 'credentials');
	for (const [name, entry] of Object.entries(known)) {
		if (name in supportedNodes) throw new Error(`Credential ${name} is in more than one package`);
		// Like stock, a package prefixes only the supported nodes of its own credentials.
		supportedNodes[name] = (entry.supportedNodes ?? []).map((node) => `${pkg.name}.${node}`);
	}
	credentialEntries.push(...loaderEntries(pkg, known).map((line) => line.slice(1)));
}

writeFileSync(
	path.join(out, 'credential-loaders.ts'),
	`${HEADER}import type { ICredentialType } from 'n8n-workflow';

import { instantiate } from '../runtime/instantiate';

export const credentialLoaders: Record<string, () => Promise<ICredentialType>> = {
${credentialEntries.join('\n')}
};

export const credentialSupportedNodes: Record<string, string[]> = ${JSON.stringify(supportedNodes)};
`,
);
